const originalAttributes = new WeakMap();

function setLanguage(language) {
  const selected = language === 'vi' ? 'vi' : 'en';
  const translate = (value) => selected === 'vi'
    ? (vietnameseTranslations[value.replace(/\s+/g, ' ').trim()] ?? value)
    : value;
  const walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (node.parentElement.closest('script, style, .language-switch, code, .baccm-concepts dt')) continue;
    if (!originalText.has(node)) originalText.set(node, node.nodeValue);
    const source = originalText.get(node);
    node.nodeValue = source.replace(/\S[\s\S]*\S|\S/, (text) => translate(text));
  }
  document.querySelectorAll('[aria-label], [alt], meta[name="description"]').forEach((element) => {
    if (!originalAttributes.has(element)) originalAttributes.set(element, new Map());
    const sources = originalAttributes.get(element);
    for (const attribute of ['aria-label', 'alt', 'content']) {
      if (!element.hasAttribute(attribute)) continue;
      if (!sources.has(attribute)) sources.set(attribute, element.getAttribute(attribute));
      element.setAttribute(attribute, translate(sources.get(attribute)));
    }
  });
  document.querySelectorAll('img[data-src-en][data-src-vi]').forEach((element) => {
    const source = element.getAttribute(`data-src-${selected}`);
    element.setAttribute('src', source);
    for (const dimension of ['width', 'height']) {
      const value = element.getAttribute(`data-${dimension}-${selected}`);
      if (value) element.setAttribute(dimension, value);
    }
    const link = element.closest('a.flower-diagram-link');
    if (link) link.setAttribute('href', source);
  });
  document.documentElement.lang = selected;
  document.querySelectorAll('[data-language]').forEach((button) => {
    button.setAttribute('aria-pressed', String(button.dataset.language === selected));
  });
  try { localStorage.setItem('hoatheomua-language', selected); } catch { /* Storage may be unavailable for local files. */ }
}

function initializeLanguage() {
  document.documentElement.normalize();
  let language = 'en';
  try { language = localStorage.getItem('hoatheomua-language') || language; } catch { /* Use English by default. */ }
  document.querySelectorAll('[data-language]').forEach((button) => {
    button.addEventListener('click', () => setLanguage(button.dataset.language));
  });
  setLanguage(language);
}
